export const KEY='roam-together-v1';
export const uid=()=>crypto.randomUUID();
export const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:n%100?2:0}).format(n/100);
export const days=(a,b)=>Math.round((Date.parse(b)-Date.parse(a))/86400000)+1;
export function validate(t,plans=[]){const n=days(t.start,t.end);if(!Number.isFinite(n)||n<1||n>31)throw Error('Choose dates in order, with no more than 31 calendar days including both endpoints.');if(plans.some(p=>p.date<t.start||p.date>t.end))throw Error('An existing plan falls outside these dates. Remove that plan or expand the trip dates.');if(!t.name.trim()||!t.destination.trim())throw Error('Enter a trip name and destination.');if(!Number.isSafeInteger(t.budget)||t.budget<0)throw Error('Enter a valid USD budget.');}
export function balances(t){const total=t.expenses.reduce((s,e)=>s+e.amount,0),q=Math.floor(total/t.people.length),r=total%t.people.length;return t.people.map((name,i)=>({name,share:q+(i<r?1:0),balance:t.expenses.filter(e=>e.payer===name).reduce((s,e)=>s+e.amount,0)-q-(i<r?1:0)}));}
export function seed(){return {id:'lisbon',name:'A little Lisbon escape',destination:'Lisbon, Portugal',start:'2027-05-21',end:'2027-05-25',budget:450000,people:['Drew','Maya','Alex','Sam','Jordan','Taylor'],plans:[{id:'p1',date:'2027-05-21',title:'Touch down in Lisbon',time:'10:30',location:'Humberto Delgado Airport',type:'Travel'},{id:'p2',date:'2027-05-21',title:'Lunch at Time Out Market',time:'13:00',location:'Mercado da Ribeira',type:'Food & drink'},{id:'p3',date:'2027-05-21',title:'Get lost in Alfama',time:'16:00',location:'Alfama · cobbled streets & little cafés',type:'Explore'}],ideas:[{id:'i1',title:'A little escape to Sintra',description:'Fairytale palaces, forest walks, and a day out of the city.',category:'Experiences',votes:4,voted:false},{id:'i2',title:'Our home in Alfama',description:'A sunny apartment with a balcony and room for everyone.',category:'Stays',votes:3,voted:false},{id:'i3',title:'Pastéis & coffee mornings',description:'Start slow with something sweet at Pastéis de Belém.',category:'Food & drink',votes:5,voted:false}],checklist:[{title:'Pick our destination',done:true},{title:'Choose our dates',done:true},{title:'Get the group together',done:true},{title:'Find a place to stay',done:false},{title:'Plan the little adventures',done:false}],expenses:[{id:'e1',description:'Our Alfama apartment',amount:132000,payer:'Maya',category:'Stays'},{id:'e2',description:'Airport transfers',amount:18000,payer:'Drew',category:'Transport'},{id:'e3',description:'First night dinner',amount:12000,payer:'Alex',category:'Food & drink'}],chat:[{name:'Maya',text:'Lisbon is officially happening! ☀️',time:'9:41 AM'},{name:'Alex',text:'Already thinking about the pastries.',time:'9:43 AM'}]};}
